<?php
declare(strict_types=1); namespace App\Services\ParentPortal;
use App\Models\{GuardianProfile,StudentGuardian,StudentLeaveRequest,StudentLeaveRequestTransition}; use App\Models\User; use Illuminate\Auth\Access\AuthorizationException; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class StudentLeaveService { public function submit(GuardianProfile $guardian,array $data):StudentLeaveRequest { if(!StudentGuardian::where('guardian_id',$guardian->id)->where('student_id',$data['student_id'])->where('can_request_leave',true)->exists())throw new AuthorizationException; return DB::transaction(function()use($guardian,$data){$leave=StudentLeaveRequest::create($data+['guardian_id'=>$guardian->id,'status'=>'pending','submitted_at'=>now()]);$this->audit($leave,'pending','pending',$guardian->user_id,'Pengajuan dibuat');activity('izin-siswa')->causedBy($guardian->user)->performedOn($leave)->log('Orang tua mengajukan izin siswa.');return $leave;}); } public function transition(StudentLeaveRequest $leave,string $status,User $actor,?string $note=null):StudentLeaveRequest { if(!in_array($status,['approved','rejected','cancelled'],true)||$leave->status!=='pending')throw ValidationException::withMessages(['status'=>'Perubahan status izin tidak valid.']);return DB::transaction(function()use($leave,$status,$actor,$note){$from=$leave->status;$leave->update(['status'=>$status,'reviewed_by'=>$status==='cancelled'?null:$actor->id,'reviewed_at'=>now(),'reviewer_note'=>$note]);$this->audit($leave,$from,$status,$actor->id,$note);activity('izin-siswa')->causedBy($actor)->performedOn($leave)->withProperties(compact('from','status'))->log('Status izin siswa berubah.');return $leave;}); } private function audit(StudentLeaveRequest $l,string $from,string $to,int $actor,?string $note):void{StudentLeaveRequestTransition::create(['student_leave_request_id'=>$l->id,'from_status'=>$from,'to_status'=>$to,'actor_id'=>$actor,'note'=>$note,'transitioned_at'=>now()]);} }
